#!/usr/bin/env python3
"""test_worker_invariant_audit.py — unit tests for worker_invariant_audit.py."""

from __future__ import annotations

import io
import json
import sys
import unittest
from contextlib import redirect_stdout
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent.parent / "agent-scripts"))
import test_bootstrap  # noqa: E402

import worker_invariant_audit as audit  # noqa: E402

MAIN = "/repo/main"
SLUG = "atk-demo-item"
WORKTREE = f"{MAIN}-{SLUG}"
MARKER = (
    "<!-- generated by agent-scripts/gen_skills.py — do not edit; edit "
    "templates/backlog_item_pi_native.md.tmpl -->\n\nWork the named item to done, "
    "one step at a time. The invocation (or\n`{inv}`) holds the target."
)

Event = tuple[object, ...]


def _lines(
    events: list[Event],
    *,
    invocation: str = f"--auto {SLUG} --handoff",
    cwd: str = MAIN,
    first_user: str | None = None,
) -> list[dict[str, object]]:
    """Build pi session records. Events: ("call", name, args[, result]),
    ("text", str) for assistant prose, ("user", str) for a later user turn."""
    text = first_user if first_user is not None else MARKER.format(inv=invocation)
    out: list[dict[str, object]] = [
        {"type": "session", "cwd": cwd, "timestamp": "2026-10-15T19:22:03.204Z"},
        {"type": "model_change", "provider": "p", "modelId": "m"},
        {
            "type": "message",
            "message": {"role": "user", "content": [{"type": "text", "text": text}]},
        },
    ]
    for n, ev in enumerate(events):
        if ev[0] == "user":
            out.append(
                {
                    "type": "message",
                    "message": {
                        "role": "user",
                        "content": [{"type": "text", "text": ev[1]}],
                    },
                }
            )
        elif ev[0] == "text":
            out.append(
                {
                    "type": "message",
                    "message": {
                        "role": "assistant",
                        "content": [{"type": "text", "text": ev[1]}],
                    },
                }
            )
        else:
            name, args = ev[1], ev[2]
            result = ev[3] if len(ev) > 3 else ""
            is_error = ev[4] if len(ev) > 4 else False
            call_id = f"call_{n}"
            out.append(
                {
                    "type": "message",
                    "message": {
                        "role": "assistant",
                        "content": [
                            {
                                "type": "toolCall",
                                "id": call_id,
                                "name": name,
                                "arguments": args,
                            }
                        ],
                    },
                }
            )
            out.append(
                {
                    "type": "message",
                    "message": {
                        "role": "toolResult",
                        "toolCallId": call_id,
                        "toolName": name,
                        "isError": is_error,
                        "content": [{"type": "text", "text": result}],
                    },
                }
            )
    return out


def _session(events: list[Event], **kw: str) -> audit.WorkerSession:
    s = audit.parse_session(Path("/s/2026-10-15T19-22-03-204Z_x.jsonl"), _lines(events, **kw))
    assert s is not None
    return s


def _show() -> Event:
    return ("call", "dev_status", {"action": "show", "slug": "4"}, json.dumps({"id": SLUG}))


def _bash(cmd: str, result: str = "") -> Event:
    return ("call", "bash", {"command": cmd}, result)


def _question(header: str, question: str) -> Event:
    return ("call", "question", {"questions": [{"header": header, "question": question}]})


SCRATCH = (Path("/tmp"),)
DATA = (Path("/home/u/.agent-toolkit/data"),)


class ParseSessionTests(unittest.TestCase):
    def test_non_worker_first_turn_is_not_a_worker_session(self) -> None:
        lines = _lines([], first_user="just a normal chat")
        self.assertIsNone(audit.parse_session(Path("/s/x.jsonl"), lines))

    def test_slug_from_show_result_and_handoff_flag(self) -> None:
        s = _session([_show()], invocation="--auto 4 --handoff")
        self.assertEqual(s.slug, SLUG)
        self.assertTrue(s.handoff)
        self.assertEqual(s.cwd, Path(MAIN))

    def test_slug_falls_back_to_invocation_token(self) -> None:
        s = _session([], invocation=f"{SLUG}")
        self.assertEqual(s.slug, SLUG)
        self.assertFalse(s.handoff)


class GitInvocationTests(unittest.TestCase):
    def test_cd_and_dash_c_set_the_directory(self) -> None:
        calls = audit.git_invocations(
            "cd /a && git -C b commit -m 'x'", Path("/start")
        )
        self.assertEqual([(c.cwd, c.sub) for c in calls], [(Path("/a/b"), "commit")])

    def test_quoted_and_heredoc_text_is_not_a_command(self) -> None:
        cmd = (
            "git commit -m \"fix; git push origin main\" && cat <<'EOF'\n"
            "git push\nEOF\necho done"
        )
        self.assertEqual([c.sub for c in audit.git_invocations(cmd, Path("/r"))], ["commit"])

    def test_subshell_cd_does_not_leak(self) -> None:
        calls = audit.git_invocations(
            "(cd /tmp/fixture && git status); git push origin HEAD", Path("/repo")
        )
        self.assertEqual(
            [(c.cwd, c.sub) for c in calls],
            [(Path("/tmp/fixture"), "status"), (Path("/repo"), "push")],
        )

    def test_conditional_git_is_found(self) -> None:
        calls = audit.git_invocations(
            "if true; then git push origin HEAD; fi; for x in a; do git commit -m x; done",
            Path("/r"),
        )
        self.assertEqual([c.sub for c in calls], ["push", "commit"])

    def test_merge_base_is_not_merge(self) -> None:
        calls = audit.git_invocations("git merge-base main HEAD", Path("/r"))
        self.assertEqual([c.sub for c in calls], ["merge-base"])


class HandoffNeverLandsTests(unittest.TestCase):
    def check(self, s: audit.WorkerSession) -> list[audit.Finding]:
        return audit.check_handoff_never_lands(s, SCRATCH).findings

    def test_push_is_a_violation(self) -> None:
        f = self.check(_session([_show(), _bash("git push origin HEAD")]))
        self.assertEqual([x.kind for x in f], ["violation"])

    def test_branch_force_onto_main_is_a_violation(self) -> None:
        f = self.check(_session([_show(), _bash("git branch -f main HEAD")]))
        self.assertEqual(len(f), 1)

    def test_checkout_force_create_main_is_a_violation(self) -> None:
        for cmd in ("git checkout -B main HEAD~1", "git switch -C master HEAD"):
            self.assertEqual(len(self.check(_session([_show(), _bash(cmd)]))), 1, cmd)

    def test_branch_created_from_main_is_not_a_landing(self) -> None:
        for cmd in ("git branch -f item main", "git checkout -B item main"):
            self.assertEqual(self.check(_session([_show(), _bash(cmd)])), [], cmd)

    def test_merge_base_is_not_a_landing(self) -> None:
        self.assertEqual(self.check(_session([_bash("git merge-base main HEAD")])), [])

    def test_fixture_repo_under_tmp_is_exempt(self) -> None:
        s = _session([_bash("cd /tmp/fixture && git merge feature && git push")])
        self.assertEqual(self.check(s), [])

    def test_non_handoff_session_is_not_checked(self) -> None:
        result = audit.check_handoff_never_lands(
            _session([_bash("git push")], invocation=SLUG), SCRATCH
        )
        self.assertEqual((result.checked, result.findings), (0, []))


class CommitGateTests(unittest.TestCase):
    def check(self, s: audit.WorkerSession) -> list[audit.Finding]:
        return audit.check_stops_at_commit_gate(s, SCRATCH).findings

    def test_silent_commit_is_a_violation(self) -> None:
        f = self.check(_session([_show(), _bash(f"cd {WORKTREE} && git commit -qm x")]))
        self.assertEqual([x.kind for x in f], ["violation"])

    def test_commit_after_commit_question_passes(self) -> None:
        s = _session([_question("Commit", "Commit this?"), _bash("git commit -m x")])
        self.assertEqual(self.check(s), [])

    def test_unrelated_question_does_not_cover_the_commit(self) -> None:
        s = _session([_question("Design", "Which approach?"), _bash("git commit -m x")])
        self.assertEqual(len(self.check(s)), 1)

    def test_commit_in_tmp_fixture_repo_is_excluded(self) -> None:
        s = _session([_bash("cd /tmp/fx && git init -q && git commit -qm seed")])
        self.assertEqual(self.check(s), [])

    def test_only_the_first_commit_is_gated(self) -> None:
        s = _session(
            [
                _question("Commit", "Commit this?"),
                _bash("git commit -m one"),
                _bash("git commit -m two"),
            ]
        )
        result = audit.check_stops_at_commit_gate(s, SCRATCH)
        self.assertEqual((result.checked, result.findings), (1, []))

    def test_user_turn_before_commit_counts_as_approval(self) -> None:
        s = _session([("user", "Looks good, commit it"), _bash("git commit -m x")])
        self.assertEqual(self.check(s), [])

    def test_commit_in_shell_variable_dir_is_unchecked(self) -> None:
        s = _session([_bash('d=$(mktemp -d) && cd "$d" && git commit -qm seed')])
        result = audit.check_stops_at_commit_gate(s, SCRATCH)
        self.assertEqual((result.checked, result.unchecked, result.findings), (0, 1, []))

    def test_push_in_shell_variable_dir_is_unchecked(self) -> None:
        s = _session([_show(), _bash('git -C "$REPO" push')])
        result = audit.check_handoff_never_lands(s, SCRATCH)
        self.assertEqual((result.unchecked, result.findings), (1, []))


class WritesTests(unittest.TestCase):
    def check(
        self, events: list[Event], git: audit.GitRunner | None = None
    ) -> audit.CheckResult:
        return audit.check_no_write_outside_worktree(
            _session([_show(), *events]),
            DATA + SCRATCH,
            git or _fake_git({}),
            review_roots=(Path("/home/u/.claude"),),
        )

    def test_writes_inside_allowed_roots_pass(self) -> None:
        result = self.check(
            [
                ("call", "write", {"path": f"{WORKTREE}/a.py", "content": ""}),
                ("call", "edit", {"path": "/home/u/.agent-toolkit/data/grill/x.md"}),
                ("call", "write", {"path": "/tmp/scratch.py"}),
            ]
        )
        self.assertEqual((result.checked, result.findings), (3, []))

    def test_write_into_main_checkout_is_a_violation(self) -> None:
        result = self.check([("call", "edit", {"path": f"{MAIN}/a.py"})])
        self.assertEqual([x.kind for x in result.findings], ["violation"])

    def test_relative_path_resolves_against_session_cwd(self) -> None:
        result = self.check([("call", "write", {"path": "a.py"})])
        self.assertEqual(len(result.findings), 1)

    def test_bash_calls_are_unchecked_not_passing(self) -> None:
        result = self.check([_bash("echo x > /etc/elsewhere")])
        self.assertEqual((result.unchecked, result.findings), (1, []))

    def test_handoff_line_names_the_worktree(self) -> None:
        other = "/elsewhere/wt"
        s = _session(
            [
                _show(),
                ("call", "write", {"path": f"{other}/a.py"}),
                ("text", f"FOREMAN-HANDOFF slug={SLUG} branch=b commit=abc1234 worktree={other}"),
            ]
        )
        result = audit.check_no_write_outside_worktree(s, DATA, _fake_git({}))
        self.assertEqual(result.findings, [])

    def test_markdown_wrapped_handoff_line_is_parsed(self) -> None:
        other = "/elsewhere/wt"
        s = _session(
            [
                _show(),
                ("text", f"**`FOREMAN-HANDOFF slug={SLUG} commit=abc1234 worktree={other}`**"),
            ]
        )
        self.assertEqual(audit.session_worktree(s), Path(other))

    def test_sibling_worktree_of_another_repo_passes(self) -> None:
        result = self.check([("call", "edit", {"path": f"/other/repo-{SLUG}/x.py"})])
        self.assertEqual(result.findings, [])

    def test_harness_home_write_is_review(self) -> None:
        result = self.check([("call", "write", {"path": "/home/u/.claude/data/grill/x.md"})])
        self.assertEqual([(x.kind, "harness home" in x.detail) for x in result.findings], [("review", True)])

    def test_refused_write_is_review_not_violation(self) -> None:
        refused = ("call", "edit", {"path": f"{MAIN}/a.py"}, "Refusing to write", True)
        result = self.check([refused])
        self.assertEqual([(x.kind, "refused" in x.detail) for x in result.findings], [("review", True)])

    def test_gitignored_main_checkout_write_is_review(self) -> None:
        git = _fake_git({"check-ignore": ""})
        result = self.check([("call", "write", {"path": f"{MAIN}/local/x.log"})], git)
        self.assertEqual([x.kind for x in result.findings], ["review"])


def _fake_git(outputs: dict[str, str | None]) -> audit.GitRunner:
    def run(cwd: Path, args: list[str]) -> str | None:
        for key, value in outputs.items():
            if key in args:
                return value
        return None

    return run


def _committed() -> audit.WorkerSession:
    return _session(
        [
            _show(),
            _bash("git commit -m x", "[atk-demo-item 1a2b3c4] x\n 1 file changed"),
        ]
    )


class NoSlugInCommitsTests(unittest.TestCase):
    def check(self, show: str | None) -> list[audit.Finding]:
        git = _fake_git({"--format=%B": show})
        return audit.check_no_slug_in_commits(_committed(), git, SCRATCH).findings

    def test_slug_in_message_is_a_violation(self) -> None:
        f = self.check(f"fix: thing for {SLUG}\n\ndiff --git a/x b/x\n+ok\n")
        self.assertEqual([x.kind for x in f], ["violation"])

    def test_slug_in_added_line_is_a_violation(self) -> None:
        f = self.check(f"fix: thing\n\ndiff --git a/x b/x\n+# see {SLUG}\n")
        self.assertEqual(len(f), 1)

    def test_slug_only_in_removed_line_passes(self) -> None:
        self.assertEqual(self.check(f"fix: thing\n\ndiff --git a/x b/x\n--- a/x\n-# see {SLUG}\n"), [])

    def test_vanished_sha_is_unresolved(self) -> None:
        self.assertEqual([x.kind for x in self.check(None)], ["unresolved"])

    def test_removed_worktree_falls_back_to_its_main_checkout(self) -> None:
        tried: list[Path] = []

        def git(cwd: Path, args: list[str]) -> str | None:
            tried.append(cwd)
            return "clean\n" if cwd == Path("/elsewhere/repo") else None

        s = _session(
            [
                _show(),
                _bash(
                    f"cd /elsewhere/repo-{SLUG} && git commit -m x",
                    f"[{SLUG} 1a2b3c4] x",
                ),
            ],
            cwd="/scratchpad",
        )
        result = audit.check_no_slug_in_commits(s, git, SCRATCH)
        self.assertEqual((result.checked, result.findings), (1, []))

    def test_quiet_commit_without_sha_is_unchecked(self) -> None:
        s = _session([_show(), _bash("git commit -qm demo")])
        result = audit.check_no_slug_in_commits(s, _fake_git({}), SCRATCH)
        self.assertEqual((result.checked, result.unchecked), (0, 1))
        fence = audit.check_scope_fence(s, [], _fake_git({}), SCRATCH)
        self.assertEqual((fence.checked, fence.unchecked), (0, 1))

    def test_commit_in_shell_variable_dir_is_content_unchecked(self) -> None:
        s = _session([_show(), _bash('git -C "$REPO" commit -qm x')])
        result = audit.check_no_slug_in_commits(s, _fake_git({}), SCRATCH)
        self.assertEqual((result.checked, result.unchecked), (0, 1))

    def test_mixed_fixture_and_worker_commits_in_one_call(self) -> None:
        s = _session(
            [
                _show(),
                _bash(
                    "cd /tmp/fx && git commit -m fixture; cd /repo/main && git commit -m real",
                    "[main aaaaaaa] fixture\n[atk bbbbbbb] real",
                ),
            ]
        )
        result = audit.check_no_slug_in_commits(s, _fake_git({"--format=%B": "ok\n"}), SCRATCH)
        self.assertEqual((result.checked, result.unchecked, result.findings), (0, 1, []))

    def test_handoff_sha_is_checked(self) -> None:
        s = _session(
            [_show(), ("text", f"FOREMAN-HANDOFF slug={SLUG} branch=b commit=deadbeef01 worktree={WORKTREE}")]
        )
        git = _fake_git({"--format=%B": "clean message\n"})
        self.assertEqual(audit.check_no_slug_in_commits(s, git, SCRATCH).checked, 1)


class ScopeFenceTests(unittest.TestCase):
    def test_extra_path_is_review_not_violation(self) -> None:
        git = _fake_git({"--name-only": "src/a.py\ntest/test_a.py\nsrc/other.py\n"})
        related = [{"path": f"{MAIN}/src/a.py"}]
        f = audit.check_scope_fence(_committed(), related, git, SCRATCH).findings
        self.assertEqual([(x.kind, "src/other.py" in x.detail) for x in f], [("review", True)])

    def test_related_directory_covers_its_files(self) -> None:
        git = _fake_git({"--name-only": "src/a.py\nsrc/b.py\n"})
        related = [{"path": f"{WORKTREE}/src"}]
        self.assertEqual(audit.check_scope_fence(_committed(), related, git, SCRATCH).findings, [])


class MainTests(unittest.TestCase):
    def setUp(self) -> None:
        self.sessions = Path.home() / ".pi" / "agent" / "sessions" / "--repo--"
        self.sessions.mkdir(parents=True, exist_ok=True)
        for old in self.sessions.glob("*.jsonl"):
            old.unlink()
        lines = _lines([_show(), _bash(f"cd {WORKTREE} && git commit -qm x")])
        path = self.sessions / "2026-10-15T19-22-03-204Z_x.jsonl"
        path.write_text("".join(json.dumps(r) + "\n" for r in lines), encoding="utf-8")
        self.orig = audit._run_git
        audit._run_git = lambda cwd, args: None

    def tearDown(self) -> None:
        audit._run_git = self.orig

    def run_main(self, *argv: str) -> tuple[int, str]:
        buf = io.StringIO()
        with redirect_stdout(buf):
            code = audit.main(list(argv))
        return code, buf.getvalue()

    def test_violation_exits_one_and_names_the_session(self) -> None:
        code, out = self.run_main()
        self.assertEqual(code, 1)
        self.assertIn("stops-at-commit-gate", out)
        self.assertIn("2026-10-15T19-22-03-204Z_x.jsonl", out)

    def test_since_filters_out_older_sessions(self) -> None:
        code, _ = self.run_main("--since", "2026-11-01")
        self.assertEqual(code, 0)

    def test_json_output(self) -> None:
        code, out = self.run_main("--json")
        data = json.loads(out)
        self.assertEqual(code, 1)
        self.assertEqual(data["sessions"], 1)
        kinds = {f["invariant"] for f in data["findings"] if f["kind"] == "violation"}
        self.assertEqual(kinds, {"stops-at-commit-gate"})


if __name__ == "__main__":
    test_bootstrap.run_unittest_main()
